create extension if not exists pgcrypto;
create table if not exists profiles (id uuid primary key,email text unique not null,full_name text,role text not null default 'user' check (role in ('super_admin','admin','editor','user')),created_at timestamptz not null default now());
create table if not exists categories (id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,parent_id uuid references categories(id) on delete cascade);
create table if not exists documents (id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id) on delete cascade,title text not null,file_path text not null,mime_type text not null default 'application/pdf',total_pages int not null default 0,language text,description text,source_type text default 'upload',classification_confidence numeric(5,2),is_public boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists document_categories (document_id uuid references documents(id) on delete cascade,category_id uuid references categories(id) on delete cascade,is_primary boolean not null default false,confidence numeric(5,2),primary key(document_id,category_id));
create table if not exists tags (id uuid primary key default gen_random_uuid(),name text unique not null);
create table if not exists document_tags (document_id uuid references documents(id) on delete cascade,tag_id uuid references tags(id) on delete cascade,primary key(document_id,tag_id));
create table if not exists reading_progress (user_id uuid references profiles(id) on delete cascade,document_id uuid references documents(id) on delete cascade,last_page int not null default 1,pages_viewed int[] not null default '{}',reading_seconds int not null default 0,completion_percent numeric(5,2) not null default 0,first_opened_at timestamptz not null default now(),last_opened_at timestamptz not null default now(),completed_at timestamptz,primary key(user_id,document_id));
create table if not exists keynotes (id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,document_id uuid references documents(id) on delete cascade,page_number int,selected_text text,selector_json jsonb,type text not null default 'important',content text,importance int not null default 3 check (importance between 1 and 5),tags text[] not null default '{}',hypothesis_annotation_id text,created_at timestamptz not null default now());
create table if not exists references_library (id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id) on delete cascade,document_id uuid references documents(id) on delete set null,type text,title text not null,authors jsonb not null default '[]',year int,publisher text,doi text,isbn text,url text,abstract text,bibtex text,csl_json jsonb,created_at timestamptz not null default now());
create table if not exists quizzes (id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id) on delete cascade,title text not null,mode text not null default 'practice',duration_minutes int,created_at timestamptz not null default now());
create table if not exists questions (id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id) on delete cascade,document_id uuid references documents(id) on delete set null,page_number int,source_excerpt text,question text not null,explanation text,difficulty text not null default 'medium',type text not null default 'multiple_choice',status text not null default 'ai_generated',created_at timestamptz not null default now());
create table if not exists question_choices (id uuid primary key default gen_random_uuid(),question_id uuid references questions(id) on delete cascade,answer text not null,is_correct boolean not null default false);
create table if not exists quiz_attempts (id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,score numeric(5,2),started_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists agenda_events (id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id) on delete cascade,title text not null,starts_at timestamptz not null,ends_at timestamptz,event_type text default 'revision',document_id uuid references documents(id) on delete set null,external_provider text,external_id text);
create table if not exists integrations (id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id) on delete cascade,provider text not null,config jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),unique(owner_id,provider));
